def build_pipeline(db):
    team = db.table("Team")

    # Filter to Queens Park Rangers
    qpr = team.filter(lambda r: r["team_long_name"] == "Queens Park Rangers")

    # Recover the dropped team_short_name column via semantic operator
    with_short_name = qpr.sem_map(cols=[
        {"name": "team_short_name", "type": str,
         "desc": "The official short/abbreviated name of the football team given its full name (team_long_name). Output just the short name token, nothing else. E.g. for 'Queens Park Rangers' the short name is the common abbreviation used in football contexts."}
    ])

    return with_short_name.project(["team_short_name"])

def build_pipeline(db):
    # The `height` column was dropped; recover it via sem_map using player identity signals
    players = db.table("Player").project(["player_name", "weight"])

    players_with_height = players.sem_map(cols=[
        {
            "name": "height",
            "type": float,
            "desc": (
                "The player's height in cm as a plain number (e.g. 182.0). "
                "Use the player's name to look up their known height. "
                "Output only the numeric value, nothing else."
            )
        }
    ])

    tall_players = players_with_height.filter(
        lambda r: r["height"] is not None and r["height"] > 180
    )

    return tall_players.project(["player_name"])

def build_pipeline(db):
    # Step 1: filter superhero table to just Copycat
    copycat = db.table("superhero").filter(lambda r: r["superhero_name"] == "Copycat")

    # Step 2: recover the dropped race_id/race via sem_map
    copycat_with_race = copycat.sem_map(cols=[
        {
            "name": "race",
            "type": str,
            "desc": (
                "The race/species of the superhero named Copycat. "
                "Output ONLY the bare race label exactly as it would appear in a race table "
                "(e.g. 'Human', 'Mutant', 'Alien'). No explanation, no extra words."
            )
        }
    ])

    # Step 3: join with race table to validate and get canonical race name
    race_table = db.table("race")

    joined = copycat_with_race.join(race_table, on="race")

    # Step 4: return just the race column
    return joined.project(["race"])

