def build_pipeline(db):
    import palimpzest as pz

    superheroes = db.table("superhero")

    # Recover publisher_name per hero — publisher_id column is dropped from superhero
    sh_slim = superheroes.project(["id", "superhero_name"])
    sh_with_pub = sh_slim.sem_map(cols=[
        {
            "name": "publisher_name",
            "type": str,
            "desc": (
                "The name of the comics publisher that publishes this superhero. "
                "Output only the publisher name exactly as it appears, e.g. 'Marvel Comics', "
                "'DC Comics', 'Image Comics'. Nothing else."
            )
        }
    ])

    # Keep only Marvel Comics heroes
    marvel = sh_with_pub.filter(lambda r: r["publisher_name"] == "Marvel Comics")

    # Determine whether each Marvel hero has the super power 'Super Strength'
    # hero_power.hero_id is dropped so the relational join path is unavailable
    marvel_with_flag = marvel.sem_map(cols=[
        {
            "name": "has_super_strength",
            "type": int,
            "desc": (
                "1 if this superhero has the super power called 'Super Strength', "
                "0 if they do not. Output only the integer 1 or 0, nothing else."
            )
        }
    ])

    # Compute percentage = (count with Super Strength / total count) * 100
    result = marvel_with_flag.sem_agg(
        col={
            "name": "percentage",
            "type": float,
            "desc": (
                "The percentage of Marvel Comics superheroes who have Super Strength, "
                "computed as (number of rows where has_super_strength = 1) / "
                "(total number of rows) * 100. Output only the numeric value."
            )
        },
        agg=(
            "Sum the has_super_strength column to count heroes with Super Strength, "
            "divide by the total number of rows, multiply by 100. "
            "Return only the resulting numeric value."
        )
    )

    return result.project(["percentage"])

def build_pipeline(db):
    # Load Player table; 'birthday' column was dropped and must be recovered by LLM
    players = db.table("Player")

    # Project to only the fields needed to identify each player for the LLM
    players_slim = players.project(["player_name", "player_api_id", "player_fifa_api_id", "weight"])

    # Recover the dropped 'birthday' column via sem_map
    players_with_birthday = players_slim.sem_map(
        cols=[{
            "name": "birthday",
            "type": str,
            "desc": (
                "The player's date of birth in YYYY-MM-DD format (e.g. '1970-10-15'). "
                "Output only the date string, nothing else. "
                "Use the player's name and weight to identify them."
            )
        }]
    )

    # Relational filter: birthyear 1970 AND birthmonth October
    filtered = players_with_birthday.filter(
        lambda r: (
            r["birthday"] is not None
            and isinstance(r["birthday"], str)
            and r["birthday"][:7] == "1970-10"
        )
    )

    return filtered.project(["player_name"])

def build_pipeline(db):
    constructor_results = db.table("constructorResults")
    constructors = db.table("constructors")

    # Filter constructorResults for raceId = 9
    race_9 = constructor_results.filter(lambda r: r["raceId"] == 9)

    # Join with constructors on constructorId
    joined = race_9.join(constructors, on="constructorId")

    # Project to only the columns needed for sem_map + downstream
    projected = joined.project(["constructorId", "name", "points"])

    # Recover the dropped `url` column via sem_map (it was dropped from constructors schema)
    with_url = projected.sem_map(cols=[
        {
            "name": "url",
            "type": str,
            "desc": (
                "The official introduction/Wikipedia URL of this Formula 1 constructor team. "
                "Output just the bare URL string (e.g. 'https://en.wikipedia.org/wiki/McLaren'), nothing else."
            )
        }
    ])

    # NOTE: PZ has no ORDER BY / sort, so top-10 by points cannot be enforced;
    # returning all constructors in race 9 with their URLs is the most faithful pipeline.
    return with_url.project(["url"])

def build_pipeline(db):
    drivers = db.table("drivers")

    # Project to only the columns needed for semantic identification
    drivers_slim = drivers.project(["driverId", "forename", "surname"])

    # Use LLM to filter for Japanese drivers (nationality is a dropped column)
    japanese_drivers = drivers_slim.sem_filter(
        "The driver has Japanese nationality based on their forename and surname"
    )

    # Use LLM to recover year of birth (dob is a dropped column)
    drivers_with_year = japanese_drivers.sem_map(cols=[
        {
            "name": "birth_year",
            "type": int,
            "desc": (
                "The driver's year of birth as a 4-digit integer (e.g. 1985). "
                "Output just the integer year, nothing else."
            )
        }
    ])

    # Compute age as: 2022 - birth_year + 1  (per hint)
    def compute_age(r):
        return {"age": 2022 - r["birth_year"] + 1}

    with_age = drivers_with_year.map(
        compute_age,
        cols=[{"name": "age", "type": int, "desc": "Driver age computed as 2022 - birth_year + 1"}]
    )

    # PZ has no ORDER BY / top-N sort; return all Japanese drivers with age
    # (blueprint requests youngest 8, but we faithfully surface all Japanese drivers)
    result = with_age.project(["age", "forename", "surname"])

    return result

def build_pipeline(db):
    import palimpzest as pz

    superheroes = db.table("superhero")

    # Recover the dropped alignment_id and publisher_id foreign keys via semantic inference
    heroes_with_info = superheroes.sem_map(cols=[
        {
            "name": "moral_alignment",
            "type": str,
            "desc": (
                "The moral alignment of this superhero in comics: one of 'Good', 'Bad', 'Neutral', or 'N/A'. "
                "Output just the single word, nothing else."
            )
        },
        {
            "name": "publisher_name",
            "type": str,
            "desc": (
                "The comic book publisher that publishes this superhero, "
                "e.g. 'Marvel Comics', 'DC Comics'. Output just the publisher name, nothing else."
            )
        }
    ])

    # Add integer indicator columns via pure Python
    heroes_with_indicators = heroes_with_info.map(
        lambda r: {
            "is_bad": 1 if r["moral_alignment"] == "Bad" else 0,
            "is_marvel_bad": 1 if (r["moral_alignment"] == "Bad" and r["publisher_name"] == "Marvel Comics") else 0,
            "group_key": "all"
        },
        cols=[
            {"name": "is_bad", "type": int, "desc": "1 if superhero has Bad alignment, 0 otherwise"},
            {"name": "is_marvel_bad", "type": int,
             "desc": "1 if superhero has Bad alignment AND is published by Marvel Comics, 0 otherwise"},
            {"name": "group_key", "type": str, "desc": "constant grouping key 'all'"}
        ]
    )

    # Aggregate across all rows using a constant group key
    grouped = heroes_with_indicators.groupby(
        pz.GroupBySig(
            group_by_fields=["group_key"],
            agg_funcs=["count", "sum", "sum"],
            agg_fields=["group_key", "is_bad", "is_marvel_bad"]
        )
    )
    # grouped columns: group_key, count(group_key), sum(is_bad), sum(is_marvel_bad)

    # Compute final percentage and Marvel bad count via pure Python
    result = grouped.map(
        lambda r: {
            "bad_alignment_percentage": float(r["sum(is_bad)"]) / float(r["count(group_key)"]) * 100.0,
            "marvel_bad_count": r["sum(is_marvel_bad)"]
        },
        cols=[
            {"name": "bad_alignment_percentage", "type": float,
             "desc": "percentage of all superheroes whose alignment is Bad"},
            {"name": "marvel_bad_count", "type": int,
             "desc": "count of Bad-alignment superheroes published by Marvel Comics"}
        ]
    ).project(["bad_alignment_percentage", "marvel_bad_count"])

    return result

def build_pipeline(db):
    superhero = db.table("superhero")

    # Relational filter: only Apocalypse
    apocalypse = superhero.filter(lambda r: r["superhero_name"] == "Apocalypse")

    # Keep only the name for the semantic call
    apocalypse_proj = apocalypse.project(["superhero_name"])

    # Recover the dropped skin_colour_id column via sem_map — returns canonical colour name
    with_colour = apocalypse_proj.sem_map(cols=[
        {
            "name": "colour",
            "type": str,
            "desc": (
                "The skin colour of this superhero. "
                "Output exactly the colour name as it would appear in a standard colour list "
                "(e.g. 'Grey', 'Blue', 'Green', 'No Colour'). "
                "Output just the single colour word/phrase, nothing else."
            )
        }
    ])

    return with_colour.project(["colour"])

def build_pipeline(db):
    import palimpzest as pz

    player = db.table("Player")
    pa = db.table("Player_Attributes")

    # Filter out null overall_rating before aggregation
    pa_valid = pa.filter(lambda r: r["overall_rating"] is not None)

    # Join Player with Player_Attributes on shared key player_api_id
    joined = player.join(pa_valid, on="player_api_id")

    # Project to only the columns needed to identify the max-rated player
    relevant = joined.project(["player_name", "weight", "overall_rating"])

    # Collapse all rows to find the player with the highest overall_rating
    # (PZ has no ORDER BY / LIMIT, so sem_agg is used to pick the single winner)
    best_player = relevant.sem_agg(
        col={
            "name": "player_name",
            "type": str,
            "desc": (
                "The player_name of the football player whose record has the single highest "
                "overall_rating value across all input rows. Return only the player name string, nothing else."
            ),
        },
        agg=(
            "Examine every row's overall_rating. Identify the row with the maximum overall_rating "
            "and return that row's player_name as the output value."
        ),
    )

    # Recover the birthday column (dropped from the live schema) via sem_map
    result = best_player.sem_map(
        cols=[
            {
                "name": "birthday",
                "type": str,
                "desc": (
                    "The birthday (date of birth) of the football player whose name is in player_name. "
                    "Return the date in YYYY-MM-DD format only, no other text."
                ),
            }
        ]
    )

    return result.project(["birthday"])

def build_pipeline(db):
    # Step 1: Filter superheroes by height between 170 and 190 cm
    heroes = db.table("superhero").filter(
        lambda r: r["height_cm"] is not None and 170 <= r["height_cm"] <= 190
    ).project(["id", "superhero_name"])

    # Step 2: Recover the dropped eye_colour_id / eye colour via sem_map
    # (eye_colour_id column was removed from the superhero table)
    heroes_with_eye = heroes.sem_map(cols=[
        {
            "name": "eye_color",
            "type": str,
            "desc": (
                "The eye colour of this superhero as stored in the superhero database. "
                "Return the exact colour name (e.g., 'No Colour', 'Blue', 'Brown', 'Green', 'Hazel', etc.). "
                "Output just the colour name, nothing else."
            )
        }
    ])

    # Step 3: Keep only those whose eye colour is 'No Colour'
    no_eye_color = heroes_with_eye.filter(lambda r: r["eye_color"] == "No Colour")

    # Step 4: Return distinct superhero names
    return no_eye_color.distinct(["superhero_name"]).project(["superhero_name"])

def build_pipeline(db):
    # Get superheroes - publisher_id and eye_colour_id columns were dropped
    superhero = db.table("superhero").project(["id", "superhero_name"])

    # Recover dropped columns via semantic map
    superheroes_enriched = superhero.sem_map(cols=[
        {
            "name": "publisher_name",
            "type": str,
            "desc": (
                "The name of the comic publisher that publishes this superhero. "
                "Output only the publisher name exactly as commonly known, e.g. 'Marvel Comics', 'DC Comics'. "
                "No extra text."
            )
        },
        {
            "name": "eye_color",
            "type": str,
            "desc": (
                "The eye color of this superhero. "
                "Output only the color name matching standard palette names, e.g. 'Blue', 'Brown', 'Green', 'No Colour'. "
                "No extra text."
            )
        }
    ])

    # Relational filter for Marvel Comics superheroes with blue eyes
    filtered = superheroes_enriched.filter(
        lambda r: r["publisher_name"] == "Marvel Comics" and r["eye_color"] == "Blue"
    )

    # Count matching superheroes
    return filtered.count()
